-- Role-family assessment banks for the curated career catalog.
-- Templates live in the private schema; clients receive answer-key-free quizzes.
-- Sources: W3C WCAG 2.2, OWASP Cheat Sheet Series, and Google SRE Workbook.
insert into private.checkpoint_quiz_templates (
  id, question_template, options, correct_option_id, explanation_template
) values
  ('cp_domain_software_p1', 'What clarifies expected behavior before implementing “{checkpoint}”?', '[{"id":"a","text":"A problem statement, acceptance criteria, edge cases, and API/data contracts"},{"id":"b","text":"A framework choice without a user outcome"},{"id":"c","text":"A screenshot of only the happy path"},{"id":"d","text":"A list of files with no expected behavior"}]'::jsonb, 'a', 'Explicit behavior and contracts let engineering, product, and QA agree on completion.'),
  ('cp_domain_software_p2', 'When “{checkpoint}” changes related records, what protects data consistency?', '[{"id":"a","text":"Independent writes with assumed success"},{"id":"b","text":"A loading spinner around writes"},{"id":"c","text":"A transaction and database constraints for important invariants"},{"id":"d","text":"A success message before the server responds"}]'::jsonb, 'c', 'Atomic transactions and constraints protect state under failures and concurrent requests.'),
  ('cp_domain_software_p3', 'Which verification gives reliable evidence for “{checkpoint}”?', '[{"id":"a","text":"Check only that it compiles"},{"id":"b","text":"Compare behavior with criteria, including boundary and failure cases"},{"id":"c","text":"Ask the author if it seems correct"},{"id":"d","text":"Test one viewport and input method"}]'::jsonb, 'b', 'Verification should trace to requirements and cover likely edge cases.'),
  ('cp_domain_software_p4', 'What makes “{checkpoint}” production ready?', '[{"id":"a","text":"Deploy debug credentials and remove them later"},{"id":"b","text":"Suppress errors to keep monitoring green"},{"id":"c","text":"Ship without a recovery path"},{"id":"d","text":"Review access control, privacy, observability, rollback, and failure behavior"}]'::jsonb, 'd', 'A release needs secure defaults, useful telemetry, and recovery paths.'),
  ('cp_domain_ai_data_p1', 'Before analyzing data for “{checkpoint}”, what should you establish?', '[{"id":"a","text":"Data provenance, collection assumptions, target definition, and quality limits"},{"id":"b","text":"A model architecture before inspecting labels"},{"id":"c","text":"An accuracy target without a baseline"},{"id":"d","text":"A chart style before checking population coverage"}]'::jsonb, 'a', 'Provenance, label meaning, and data quality determine whether analysis is valid.'),
  ('cp_domain_ai_data_p2', 'How should “{checkpoint}” avoid evaluation leakage?', '[{"id":"a","text":"Tune repeatedly on the final test set"},{"id":"b","text":"Normalize the full dataset before every split"},{"id":"c","text":"Split by independent unit or time before fitting transformations or selecting features"},{"id":"d","text":"Choose the split after reviewing final performance"}]'::jsonb, 'c', 'The split should reflect deployment and precede learned preprocessing.'),
  ('cp_domain_ai_data_p3', 'Which evaluation best supports a claim about “{checkpoint}”?', '[{"id":"a","text":"Report accuracy alone for an imbalanced task"},{"id":"b","text":"Use a task-appropriate metric, baseline, uncertainty, and subgroup checks"},{"id":"c","text":"Choose whichever metric looks strongest afterward"},{"id":"d","text":"Treat training score as generalization evidence"}]'::jsonb, 'b', 'A baseline and metric context make quality interpretable and reveal uneven outcomes.'),
  ('cp_domain_ai_data_p4', 'What should be monitored after “{checkpoint}” goes live?', '[{"id":"a","text":"Only whether the process is running"},{"id":"b","text":"Raw user records in public logs"},{"id":"c","text":"Training accuracy instead of live results"},{"id":"d","text":"Input quality and drift, outcome quality, privacy, and a safe fallback"}]'::jsonb, 'd', 'Production monitoring should detect degraded data/outcomes while protecting sensitive data.'),
  ('cp_domain_cloud_p1', 'Before provisioning “{checkpoint}”, what should the design define?', '[{"id":"a","text":"Service boundaries, identity needs, data classification, and reliability goals"},{"id":"b","text":"A public route for every component"},{"id":"c","text":"A production-sized cluster before estimating traffic"},{"id":"d","text":"Manual changes with no owner"}]'::jsonb, 'a', 'Architecture, trust boundaries, and user-centered goals guide safer provisioning.'),
  ('cp_domain_cloud_p2', 'Which approach best supports repeatable “{checkpoint}” deployments?', '[{"id":"a","text":"Unrecorded manual console changes"},{"id":"b","text":"One administrator credential in source control"},{"id":"c","text":"Reviewed declarative infrastructure with least-privilege identities and scoped config"},{"id":"d","text":"Production secrets hard-coded in manifests"}]'::jsonb, 'c', 'Versioned infrastructure and scoped identities make changes reviewable and repeatable.'),
  ('cp_domain_cloud_p3', 'How should “{checkpoint}” prepare for a dependency outage?', '[{"id":"a","text":"Retry forever as fast as possible"},{"id":"b","text":"Exercise timeouts, bounded retries, health signals, and recovery against an SLO"},{"id":"c","text":"Use average latency only"},{"id":"d","text":"Assume a healthy process means successful requests"}]'::jsonb, 'b', 'Bounded failure handling and user-relevant indicators support safe recovery.'),
  ('cp_domain_cloud_p4', 'What is a strong infrastructure release plan for “{checkpoint}”?', '[{"id":"a","text":"Apply everywhere at once without monitoring"},{"id":"b","text":"Delete the prior configuration immediately"},{"id":"c","text":"Store unmonitored logs and call it observability"},{"id":"d","text":"Stage the change, watch user-facing indicators, and define rollback and ownership"}]'::jsonb, 'd', 'Staging, telemetry, clear ownership, and rollback limit change impact.'),
  ('cp_domain_cybersecurity_p1', 'How should “{checkpoint}” begin a threat assessment?', '[{"id":"a","text":"Map assets, trust boundaries, sensitive data, actors, and plausible abuse cases"},{"id":"b","text":"Scan hosts without permission"},{"id":"c","text":"Assume the UI is the only attack surface"},{"id":"d","text":"Collect real credentials to test storage"}]'::jsonb, 'a', 'A scoped model of assets and boundaries turns review into actionable risk analysis.'),
  ('cp_domain_cybersecurity_p2', 'Before testing “{checkpoint}”, what should an authorized security test establish?', '[{"id":"a","text":"A way to bypass owner monitoring"},{"id":"b","text":"Production access without a time limit"},{"id":"c","text":"Written scope, permission, safe limits, and a plan to protect users"},{"id":"d","text":"Public disclosure before confirming a finding"}]'::jsonb, 'c', 'Permission and boundaries protect systems and people during security testing.'),
  ('cp_domain_cybersecurity_p3', 'A confirmed compromise affects “{checkpoint}”. What should response prioritize?', '[{"id":"a","text":"Delete logs to prevent alarm"},{"id":"b","text":"Contain exposure, preserve evidence, assess impact, and coordinate recovery"},{"id":"c","text":"Make unverified public claims"},{"id":"d","text":"Keep vulnerable access active until a report is complete"}]'::jsonb, 'b', 'Response balances containment, evidence, impact assessment, and recovery.'),
  ('cp_domain_cybersecurity_p4', 'How should remediation for “{checkpoint}” be verified?', '[{"id":"a","text":"Close the issue after a code change"},{"id":"b","text":"Treat a scanner''s green result as proof of no risk"},{"id":"c","text":"Remove the report"},{"id":"d","text":"Retest the attack path, check adjacent controls, and assign residual risk"}]'::jsonb, 'd', 'Retesting validates the fix and documents any remaining risk.'),
  ('cp_domain_mobile_p1', 'What should “{checkpoint}” define before implementation?', '[{"id":"a","text":"User tasks, target devices, lifecycle states, permissions, and offline needs"},{"id":"b","text":"One screen size and permanent connectivity"},{"id":"c","text":"Every platform permission"},{"id":"d","text":"An animation before the task flow"}]'::jsonb, 'a', 'Device, lifecycle, and network constraints shape reliable mobile behavior.'),
  ('cp_domain_mobile_p2', 'How should “{checkpoint}” handle backgrounding or process recreation?', '[{"id":"a","text":"Keep all state only in a screen instance"},{"id":"b","text":"Request every permission at startup"},{"id":"c","text":"Persist the state needed to restore the task and tolerate lifecycle transitions"},{"id":"d","text":"Assume background apps are never terminated"}]'::jsonb, 'c', 'Mobile processes can be paused or recreated, so important task state must be restored.'),
  ('cp_domain_mobile_p3', 'Which verification plan is strongest for “{checkpoint}”?', '[{"id":"a","text":"Test only on the developer''s newest phone"},{"id":"b","text":"Test supported devices, network loss, accessibility, performance, and denied permissions"},{"id":"c","text":"Ignore screen readers and larger text"},{"id":"d","text":"Assume one simulator covers every condition"}]'::jsonb, 'b', 'Representative devices and failure states reveal real-world issues.'),
  ('cp_domain_mobile_p4', 'Which release practice best protects users of “{checkpoint}”?', '[{"id":"a","text":"Collect all available personal data"},{"id":"b","text":"Release without compatibility signals"},{"id":"c","text":"Hide the purpose of permissions"},{"id":"d","text":"Review data/permissions, stage rollout, monitor crashes, and prepare rollback"}]'::jsonb, 'd', 'Privacy review and staged release with monitoring create a safer launch.'),
  ('cp_domain_game_p1', 'Before building “{checkpoint}”, what should be established?', '[{"id":"a","text":"The player outcome, interaction loop, target platform, and performance budget"},{"id":"b","text":"A high-resolution asset before the interaction"},{"id":"c","text":"A frame rate target without measuring hardware"},{"id":"d","text":"A copied mechanic without checking controls"}]'::jsonb, 'a', 'A clear loop and platform budget make design choices testable.'),
  ('cp_domain_game_p2', 'How can “{checkpoint}” keep runtime behavior predictable?', '[{"id":"a","text":"Let every object modify global state at any time"},{"id":"b","text":"Use frame-rate dependent movement with no timing model"},{"id":"c","text":"Separate state transitions from presentation and make update ownership explicit"},{"id":"d","text":"Hide configuration in magic values"}]'::jsonb, 'c', 'Explicit state ownership makes behavior easier to reason about and test.'),
  ('cp_domain_game_p3', 'What evidence shows “{checkpoint}” meets its performance target?', '[{"id":"a","text":"Count draw calls in an empty scene"},{"id":"b","text":"Profile representative scenes on target hardware and inspect frame time and memory"},{"id":"c","text":"Assume a workstation represents mobile"},{"id":"d","text":"Optimize based only on code appearance"}]'::jsonb, 'b', 'Target-device profiling reveals bottlenecks affecting player experience.'),
  ('cp_domain_game_p4', 'Which release check validates “{checkpoint}” across platforms?', '[{"id":"a","text":"Ship one build and assume platforms match"},{"id":"b","text":"Delete saves during every update"},{"id":"c","text":"Ignore crashes if it works in the editor"},{"id":"d","text":"Test input, save compatibility, performance, and recovery on each target platform"}]'::jsonb, 'd', 'Platform behavior and player data need explicit compatibility and recovery checks.'),
  ('cp_domain_design_p1', 'How should “{checkpoint}” gather evidence about users?', '[{"id":"a","text":"Identify user groups and tasks, then research without leading participants"},{"id":"b","text":"Ask only the design team what users want"},{"id":"c","text":"Treat stakeholder preference as research"},{"id":"d","text":"Choose a style before defining the problem"}]'::jsonb, 'a', 'Design decisions should connect to observed needs rather than assumptions.'),
  ('cp_domain_design_p2', 'What is the useful next step after prototyping “{checkpoint}”?', '[{"id":"a","text":"Ask only whether users like the color"},{"id":"b","text":"Explain every screen before testing"},{"id":"c","text":"Test representative user tasks and record where the design helps or blocks"},{"id":"d","text":"Polish animation before validating the flow"}]'::jsonb, 'c', 'Observed task behavior reveals usability problems better than preference alone.'),
  ('cp_domain_design_p3', 'Which review best supports inclusive use of “{checkpoint}”?', '[{"id":"a","text":"Check contrast on one screenshot only"},{"id":"b","text":"Check keyboard paths, focus, labels, contrast, reflow, and assistive semantics"},{"id":"c","text":"Remove focus indicators"},{"id":"d","text":"Use color alone to show status"}]'::jsonb, 'b', 'Accessibility includes operable interactions and understandable information.'),
  ('cp_domain_design_p4', 'What makes “{checkpoint}” ready for engineering handoff?', '[{"id":"a","text":"Provide only a static ideal-state image"},{"id":"b","text":"Leave errors and empty states to guesswork"},{"id":"c","text":"Use inconsistent components on each screen"},{"id":"d","text":"Document component states, responsive behavior, content, interaction, and open questions"}]'::jsonb, 'd', 'A strong handoff explains behavior and states, not only a screenshot.'),
  ('cp_domain_product_p1', 'How should “{checkpoint}” define success before prioritization?', '[{"id":"a","text":"State the user problem, desired outcome, baseline, and measurable indicator"},{"id":"b","text":"Count shipped features as value"},{"id":"c","text":"Choose a metric after seeing results"},{"id":"d","text":"Use an outcome that cannot be observed"}]'::jsonb, 'a', 'An outcome and baseline connect work to a user need and make impact assessable.'),
  ('cp_domain_product_p2', 'How should the team prioritize “{checkpoint}”?', '[{"id":"a","text":"Select the loudest request"},{"id":"b","text":"Treat every request as equally urgent"},{"id":"c","text":"Compare value, evidence, risk, effort, and opportunity cost against shared goals"},{"id":"d","text":"Prioritize implementation convenience alone"}]'::jsonb, 'c', 'Explicit tradeoffs tie prioritization to outcomes rather than volume or habit.'),
  ('cp_domain_product_p3', 'What is a responsible way to validate “{checkpoint}”?', '[{"id":"a","text":"Run without a stopping rule or safeguards"},{"id":"b","text":"Define a proportionate experiment with success and guardrail metrics in advance"},{"id":"c","text":"Change multiple factors and attribute one cause"},{"id":"d","text":"Ignore negative outcomes after shipping"}]'::jsonb, 'b', 'A hypothesis, guardrails, and decision rule reduce misleading conclusions.'),
  ('cp_domain_product_p4', 'After launching “{checkpoint}”, what should the product owner do?', '[{"id":"a","text":"Declare success at deployment"},{"id":"b","text":"Hide negative results"},{"id":"c","text":"Keep the feature even when it misses the goal"},{"id":"d","text":"Review outcome and guardrail metrics, gather feedback, and communicate results"}]'::jsonb, 'd', 'Post-launch evidence should inform a clear decision and stakeholder communication.'),
  ('cp_domain_qa_p1', 'How should “{checkpoint}” become a test strategy?', '[{"id":"a","text":"Map risks and acceptance criteria to suitable test levels and observable outcomes"},{"id":"b","text":"Write tests unrelated to behavior"},{"id":"c","text":"Test only by manual clicking at the end"},{"id":"d","text":"Use coverage alone as proof of quality"}]'::jsonb, 'a', 'Risk-based testing gives evidence for the failure modes that matter.'),
  ('cp_domain_qa_p2', 'A test for “{checkpoint}” is flaky. What should happen first?', '[{"id":"a","text":"Rerun until it passes and hide failures"},{"id":"b","text":"Increase all timeouts without investigation"},{"id":"c","text":"Find and remove timing, ordering, shared-state, or environment causes"},{"id":"d","text":"Delete its assertions"}]'::jsonb, 'c', 'Deterministic tests provide trustworthy feedback and make diagnosis faster.'),
  ('cp_domain_qa_p3', 'Which quality summary best informs a release decision for “{checkpoint}”?', '[{"id":"a","text":"A green badge with no scope"},{"id":"b","text":"Open risks, test evidence, affected workflows, severity, and mitigation owners"},{"id":"c","text":"Test count without results"},{"id":"d","text":"A claim of no bugs with no test description"}]'::jsonb, 'b', 'Release decisions need scope and evidence, including uncovered risks.'),
  ('cp_domain_qa_p4', 'When is “{checkpoint}” ready to release?', '[{"id":"a","text":"When the schedule says so"},{"id":"b","text":"After one passing test run"},{"id":"c","text":"When critical defects are hidden"},{"id":"d","text":"Agreed risk thresholds are met, critical defects are resolved or accepted, rollback is understood"}]'::jsonb, 'd', 'Release readiness should state accepted risk, defect status, and recovery options.'),
  ('cp_domain_fintech_p1', 'Before handling financial value, what should “{checkpoint}” define?', '[{"id":"a","text":"Currency and precision, actor permissions, lifecycle states, and reconciliation"},{"id":"b","text":"Undocumented floating-point rounding"},{"id":"c","text":"Mutable balance with no event history"},{"id":"d","text":"A client-calculated amount trusted by the server"}]'::jsonb, 'a', 'Financial correctness depends on explicit units, controlled states, and reconciliation.'),
  ('cp_domain_fintech_p2', 'How should “{checkpoint}” handle a retry after an uncertain payment response?', '[{"id":"a","text":"Create another charge when no response arrived"},{"id":"b","text":"Trust a client flag that says the request is unique"},{"id":"c","text":"Use an idempotency key and return the prior outcome for the same operation"},{"id":"d","text":"Disable retries and leave the user uncertain"}]'::jsonb, 'c', 'Idempotency prevents duplicate financial effects when networks retry.'),
  ('cp_domain_fintech_p3', 'Which control best supports auditability for “{checkpoint}”?', '[{"id":"a","text":"Overwrite prior transactions during corrections"},{"id":"b","text":"Append attributable events and reconcile totals against an independent source"},{"id":"c","text":"Let one operator initiate and approve every high-risk action"},{"id":"d","text":"Store credentials in logs"}]'::jsonb, 'b', 'Append-only history and reconciliation make changes traceable and discrepancies visible.'),
  ('cp_domain_fintech_p4', 'What is the strongest release check for “{checkpoint}”?', '[{"id":"a","text":"Check only that the success page renders"},{"id":"b","text":"Use real customer data in unprotected staging"},{"id":"c","text":"Ignore an unexplained reconciliation gap"},{"id":"d","text":"Verify authorization, duplicate handling, reconciliation, privacy, and recovery with evidence"}]'::jsonb, 'd', 'Financial releases need evidence for controls and failure recovery.'),
  ('cp_domain_hardware_p1', 'What should engineering requirements for “{checkpoint}” capture?', '[{"id":"a","text":"Environment, interfaces, power and safety limits, measurable behavior, and constraints"},{"id":"b","text":"A parts list without operating ranges"},{"id":"c","text":"An enclosure before the physical use case"},{"id":"d","text":"A pass condition based only on appearance"}]'::jsonb, 'a', 'Physical systems need measurable requirements for environment, interfaces, and safety.'),
  ('cp_domain_hardware_p2', 'How should “{checkpoint}” validate sensor or actuator behavior?', '[{"id":"a","text":"Compare readings by eye"},{"id":"b","text":"Assume nominal component values always hold"},{"id":"c","text":"Use calibrated references, known conditions, and documented tolerance limits"},{"id":"d","text":"Bypass protection to simplify tests"}]'::jsonb, 'c', 'Calibration and controlled conditions make measurements repeatable and expose tolerance failures.'),
  ('cp_domain_hardware_p3', 'A prototype for “{checkpoint}” fails intermittently. What is the best diagnostic approach?', '[{"id":"a","text":"Replace several parts at once"},{"id":"b","text":"Reproduce controlled inputs and capture timing, environment, power, and interface measurements"},{"id":"c","text":"Ignore failures that are intermittent"},{"id":"d","text":"Disable protections if the fault disappears"}]'::jsonb, 'b', 'Controlled reproduction helps isolate faults without masking risk.'),
  ('cp_domain_hardware_p4', 'What makes “{checkpoint}” ready for production handoff?', '[{"id":"a","text":"Send a prototype without test records"},{"id":"b","text":"Remove fault reporting"},{"id":"c","text":"Assume production units exactly match the prototype"},{"id":"d","text":"Document revision, calibration, safety checks, diagnostics, operating limits, and service steps"}]'::jsonb, 'd', 'Traceable revisions and diagnostics support safety and repeatability after prototyping.'),
  ('cp_domain_enterprise_p1', 'How should “{checkpoint}” begin in a complex enterprise environment?', '[{"id":"a","text":"Map stakeholder outcomes, current process, authoritative data, constraints, and decision owners"},{"id":"b","text":"Replace the workflow before documenting it"},{"id":"c","text":"Assume all departments need identical permissions"},{"id":"d","text":"Choose a vendor before mapping boundaries"}]'::jsonb, 'a', 'Enterprise delivery depends on understanding ownership, workflows, and boundaries first.'),
  ('cp_domain_enterprise_p2', 'What makes an integration for “{checkpoint}” resilient to system changes?', '[{"id":"a","text":"Couple every consumer to internal tables"},{"id":"b","text":"Ignore partial failures"},{"id":"c","text":"A versioned contract, explicit ownership, validation, and observable failure handling"},{"id":"d","text":"Share an administrator credential across services"}]'::jsonb, 'c', 'Versioned contracts limit change propagation and make failures diagnosable.'),
  ('cp_domain_enterprise_p3', 'How should “{checkpoint}” demonstrate operational control?', '[{"id":"a","text":"Assume a vendor certificate covers local processes"},{"id":"b","text":"Keep traceable approvals, access boundaries, change records, and applicable control evidence"},{"id":"c","text":"Store audit evidence only in personal email"},{"id":"d","text":"Grant broad access for convenience"}]'::jsonb, 'b', 'Traceable evidence shows who approved changes and how access is governed.'),
  ('cp_domain_enterprise_p4', 'Which rollout best manages organizational risk for “{checkpoint}”?', '[{"id":"a","text":"Switch all teams at once and announce afterward"},{"id":"b","text":"Migrate without validation"},{"id":"c","text":"Treat adoption and support as out of scope"},{"id":"d","text":"Pilot with affected users, train support, stage migration, monitor, and define rollback"}]'::jsonb, 'd', 'A staged rollout with validation and support readiness reduces disruption.')
on conflict (id) do nothing;

